//! Generated byte-level round trips and checksum corruption invariants.
use proptest::prelude::*;
use std::{collections::BTreeMap, path::PathBuf};
use thereabouts_core::format::{
    address,
    catalogue::{self, Place},
    manifest,
    spatial::{self, Label},
    verify,
};

proptest! {
    #[test]
    fn sparse_dictionary_round_trip(count in 0_usize..300, period in 1_u32..270) {
        let root = h3o::LatLng::new(48.8, 2.3).unwrap().to_cell(h3o::Resolution::Three);
        let block = address::address(root).0;
        let rows: Vec<_> = root.children(h3o::Resolution::Eight).take(count)
            .enumerate().map(|(i, cell)| {
                (address::address(cell).1, Label([1, 0, u32::try_from(i).unwrap() % period + 1, 9, 0]))
            }).collect();
        let input = BTreeMap::from([(block, rows.clone())]);
        let decoded = spatial::decode(spatial::encode_blocks(&input).unwrap(), 300, 1).unwrap();
        prop_assert_eq!(&decoded[&block].keys, &rows.iter().map(|(key, _)| *key).collect::<Vec<_>>());
        prop_assert_eq!(&decoded[&block].labels, &rows.iter().map(|(_, label)| *label).collect::<Vec<_>>());
    }

    #[test]
    fn unicode_catalogue_round_trip(name in ".{1,80}", population in any::<u32>()) {
        let place = Place {
            text: std::array::from_fn(|i| Some(if i == 11 { "{}".into() } else { name.clone() })),
            refs: [0; 4], latitude: 12_345_678, longitude: -45_678_901,
            population, timezone: Some("Europe/Paris".into()),
        };
        let decoded = catalogue::decode(catalogue::encode_places(std::slice::from_ref(&place)).unwrap()).unwrap();
        prop_assert_eq!(&decoded[0].text, &place.text);
        prop_assert_eq!(decoded[0].population, population);
        prop_assert_eq!(decoded[0].point(), place.point());
    }

    #[test]
    fn changed_shard_is_detected(position in any::<usize>(), bit in 0_u8..8) {
        let source = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../tests/fixtures/packs/core-synthetic");
        let temp = tempfile::tempdir().unwrap();
        for entry in std::fs::read_dir(&source).unwrap() {
            let entry = entry.unwrap();
            std::fs::copy(entry.path(), temp.path().join(entry.file_name())).unwrap();
        }
        let manifest = manifest::read(temp.path()).unwrap();
        let file = manifest.files.iter().find(|f| f.kind == "cells").unwrap();
        let path = temp.path().join(&file.path);
        let mut bytes = std::fs::read(&path).unwrap();
        let index = position % bytes.len();
        bytes[index] ^= 1 << bit;
        std::fs::write(path, bytes).unwrap();
        prop_assert!(verify::verify(temp.path()).is_err());
    }
}
